# Sahifa dua 20 (Makarim al-Akhlaq): vocalized by Claude, consonants checked against OpenITI Shia001112-ara1
D = {}
D[20] = dict(title='دعای مکارم الاخلاق', sub='درخواست خوی‌های نیک و کارهای پسندیده',
 intro_ar='وَكَانَ مِنْ دُعَائِهِ عَلَيْهِ السَّلَامُ فِي مَكَارِمِ الْأَخْلَاقِ وَمَرْضِيِّ الْأَفْعَالِ',
 intro_fa='از دعاهای امام سجاد (ع) در [درخواست] خوی‌های بزرگوارانه و کارهای پسندیده',
 p=[
('اللّٰهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَآلِهِ، وَبَلِّغْ بِإِيمَانِي أَكْمَلَ الْإِيمَانِ، وَاجْعَلْ يَقِينِي أَفْضَلَ الْيَقِينِ، وَانْتَهِ بِنِيَّتِي إِلَى أَحْسَنِ النِّيَّاتِ، وَبِعَمَلِي إِلَى أَحْسَنِ الْأَعْمَالِ.',
 'خدایا، بر محمد و خاندانش درود فرست، و ایمانم را به کامل‌ترین ایمان برسان، و یقینم را برترین یقین قرار ده، و نیتم را به بهترین نیت‌ها، و کارم را به بهترین کارها برسان.'),
('اللّٰهُمَّ وَفِّرْ بِلُطْفِكَ نِيَّتِي، وَصَحِّحْ بِمَا عِنْدَكَ يَقِينِي، وَاسْتَصْلِحْ بِقُدْرَتِكَ مَا فَسَدَ مِنِّي.',
 'خدایا، با لطفت نیتم را کامل کن، و با آنچه نزد توست یقینم را درست گردان، و با قدرتت آنچه از من تباه شده را اصلاح کن.'),
('اللّٰهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَآلِهِ، وَاكْفِنِي مَا يَشْغَلُنِي الِاهْتِمَامُ بِهِ، وَاسْتَعْمِلْنِي بِمَا تَسْأَلُنِي غَداً عَنْهُ، وَاسْتَفْرِغْ أَيَّامِي فِيمَا خَلَقْتَنِي لَهُ،',
 'خدایا، بر محمد و خاندانش درود فرست، و مرا از آنچه دل‌مشغولی به آن سرگرمم می‌کند کفایت کن، و مرا به کاری بگمار که فردا [ی قیامت] از آن بازخواستم می‌کنی، و روزهایم را در راهی که برای آن آفریده‌ای صرف کن.'),
('وَأَغْنِنِي وَأَوْسِعْ عَلَيَّ فِي رِزْقِكَ، وَلَا تَفْتِنِّي بِالنَّظَرِ، وَأَعِزَّنِي وَلَا تَبْتَلِيَنِّي بِالْكِبْرِ، وَعَبِّدْنِي لَكَ وَلَا تُفْسِدْ عِبَادَتِي بِالْعُجْبِ، وَأَجْرِ لِلنَّاسِ عَلَى يَدِيَ الْخَيْرَ وَلَا تَمْحَقْهُ بِالْمَنِّ، وَهَبْ لِي مَعَالِيَ الْأَخْلَاقِ، وَاعْصِمْنِي مِنَ الْفَخْرِ.',
 'و بی‌نیازم کن و روزی‌ات را بر من گشاده گردان، و مرا با چشم دوختن [به دارایی دیگران] گرفتار مکن، و عزیزم کن و به تکبر مبتلایم مساز، و مرا بندهٔ خودت کن و عبادتم را با خودپسندی تباه مکن، و خیر را برای مردم به دست من روان کن و آن را با منت گذاشتن نابود مکن، و خوی‌های والا را به من ببخش، و مرا از فخرفروشی نگاه دار.'),
('اللّٰهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَآلِهِ، وَلَا تَرْفَعْنِي فِي النَّاسِ دَرَجَةً إِلَّا حَطَطْتَنِي عِنْدَ نَفْسِي مِثْلَهَا، وَلَا تُحْدِثْ لِي عِزّاً ظَاهِراً إِلَّا أَحْدَثْتَ لِي ذِلَّةً بَاطِنَةً عِنْدَ نَفْسِي بِقَدَرِهَا.',
 'خدایا، بر محمد و خاندانش درود فرست، و مرا در میان مردم درجه‌ای بالا مبر مگر آنکه به همان اندازه در نظر خودم پایینم آوری، و برایم عزتی آشکار پدید میاور مگر آنکه به اندازهٔ آن، در نظر خودم فروتنیِ پنهانی برایم پدید آوری.'),
('اللّٰهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَآلِ مُحَمَّدٍ، وَمَتِّعْنِي بِهُدًى صَالِحٍ لَا أَسْتَبْدِلُ بِهِ، وَطَرِيقَةِ حَقٍّ لَا أَزِيغُ عَنْهَا، وَنِيَّةِ رُشْدٍ لَا أَشُكُّ فِيهَا،',
 'خدایا، بر محمد و خاندان محمد درود فرست، و مرا از هدایتی شایسته که آن را با چیزی عوض نکنم، و راه حقی که از آن منحرف نشوم، و نیت درستی که در آن تردید نکنم بهره‌مند ساز.'),
('وَعَمِّرْنِي مَا كَانَ عُمُرِي بِذْلَةً فِي طَاعَتِكَ، فَإِذَا كَانَ عُمُرِي مَرْتَعاً لِلشَّيْطَانِ فَاقْبِضْنِي إِلَيْكَ قَبْلَ أَنْ يَسْبِقَ مَقْتُكَ إِلَيَّ، أَوْ يَسْتَحْكِمَ غَضَبُكَ عَلَيَّ.',
 'و تا وقتی عمرم در طاعت تو به کار می‌رود، عمرم ده؛ و هرگاه عمرم چراگاه شیطان شد، پیش از آنکه بیزاری‌ات به سویم بشتابد یا خشمت بر من استوار گردد، جانم را به سوی خود بگیر.'),
('اللّٰهُمَّ لَا تَدَعْ خَصْلَةً تُعَابُ مِنِّي إِلَّا أَصْلَحْتَهَا، وَلَا عَائِبَةً أُؤَنَّبُ بِهَا إِلَّا حَسَّنْتَهَا، وَلَا أُكْرُومَةً فِيَّ نَاقِصَةً إِلَّا أَتْمَمْتَهَا.',
 'خدایا، هیچ خصلتی در من که سرزنش شود وامگذار مگر آنکه اصلاحش کنی، و هیچ عیبی که به خاطرش نکوهش شوم مگر آنکه نیکویش کنی، و هیچ خوی بزرگوارانهٔ ناقصی در من مگر آنکه کاملش کنی.'),
('اللّٰهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَآلِ مُحَمَّدٍ، وَأَبْدِلْنِي مِنْ بِغْضَةِ أَهْلِ الشَّنَآنِ الْمَحَبَّةَ، وَمِنْ حَسَدِ أَهْلِ الْبَغْيِ الْمَوَدَّةَ، وَمِنْ ظِنَّةِ أَهْلِ الصَّلَاحِ الثِّقَةَ، وَمِنْ عَدَاوَةِ الْأَدْنَيْنَ الْوَلَايَةَ، وَمِنْ عُقُوقِ ذَوِي الْأَرْحَامِ الْمَبَرَّةَ،',
 'خدایا، بر محمد و خاندان محمد درود فرست، و به جای کینهٔ کینه‌توزان محبت، و به جای حسد ستمگران دوستی، و به جای بدگمانی شایستگان اعتماد، و به جای دشمنی نزدیکان دوستی و یاری، و به جای بدرفتاری خویشاوندان نیکی را نصیبم کن،'),
('وَمِنْ خِذْلَانِ الْأَقْرَبِينَ النُّصْرَةَ، وَمِنْ حُبِّ الْمُدَارِينَ تَصْحِيحَ الْمِقَةِ، وَمِنْ رَدِّ الْمُلَابِسِينَ كَرَمَ الْعِشْرَةِ، وَمِنْ مَرَارَةِ خَوْفِ الظَّالِمِينَ حَلَاوَةَ الْأَمَنَةِ.',
 'و به جای تنها گذاشتنِ نزدیکان یاری، و به جای دوستیِ ظاهریِ مدارا‌کنندگان دوستیِ راستین، و به جای طرد شدن از سوی معاشران رفتار بزرگوارانه، و به جای تلخی ترس از ستمگران شیرینی امنیت را.'),
('اللّٰهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَآلِهِ، وَاجْعَلْ لِي يَداً عَلَى مَنْ ظَلَمَنِي، وَلِسَاناً عَلَى مَنْ خَاصَمَنِي، وَظَفَراً بِمَنْ عَانَدَنِي، وَهَبْ لِي مَكْراً عَلَى مَنْ كَايَدَنِي، وَقُدْرَةً عَلَى مَنِ اضْطَهَدَنِي، وَتَكْذِيباً لِمَنْ قَصَبَنِي، وَسَلَامَةً مِمَّنْ تَوَعَّدَنِي،',
 'خدایا، بر محمد و خاندانش درود فرست، و برایم در برابر کسی که به من ستم کرده توانی، و در برابر کسی که با من ستیزه کرده زبانی [گویا]، و بر کسی که با من دشمنی ورزیده پیروزی قرار ده؛ و در برابر کسی که با من نیرنگ کرده تدبیری، و بر کسی که به من زور گفته توانی، و برای [رد] کسی که به من عیب بسته دلیلی بر دروغش، و از کسی که مرا تهدید کرده سلامتی به من ببخش.'),
('وَوَفِّقْنِي لِطَاعَةِ مَنْ سَدَّدَنِي، وَمُتَابَعَةِ مَنْ أَرْشَدَنِي.',
 'و مرا به فرمان‌برداری از کسی که استوارم می‌دارد، و پیروی از کسی که راهنمایی‌ام می‌کند، توفیق ده.'),
('اللّٰهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَآلِهِ، وَسَدِّدْنِي لِأَنْ أُعَارِضَ مَنْ غَشَّنِي بِالنُّصْحِ، وَأَجْزِيَ مَنْ هَجَرَنِي بِالْبِرِّ، وَأُثِيبَ مَنْ حَرَمَنِي بِالْبَذْلِ، وَأُكَافِئَ مَنْ قَطَعَنِي بِالصِّلَةِ، وَأُخَالِفَ مَنِ اغْتَابَنِي إِلَى حُسْنِ الذِّكْرِ، وَأَنْ أَشْكُرَ الْحَسَنَةَ، وَأُغْضِيَ عَنِ السَّيِّئَةِ.',
 'خدایا، بر محمد و خاندانش درود فرست، و استوارم کن تا با کسی که با من دغلی کرده با خیرخواهی روبه‌رو شوم، و به کسی که از من دوری کرده با نیکی پاداش دهم، و به کسی که مرا محروم کرده با بخشش عوض دهم، و کسی را که از من بریده با پیوند جبران کنم، و برخلاف کسی که پشت سرم بدگویی کرده، از او به نیکی یاد کنم، و نیکی را سپاس گویم، و از بدی چشم بپوشم.'),
('اللّٰهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَآلِهِ، وَحَلِّنِي بِحِلْيَةِ الصَّالِحِينَ، وَأَلْبِسْنِي زِينَةَ الْمُتَّقِينَ، فِي بَسْطِ الْعَدْلِ، وَكَظْمِ الْغَيْظِ، وَإِطْفَاءِ النَّائِرَةِ، وَضَمِّ أَهْلِ الْفُرْقَةِ، وَإِصْلَاحِ ذَاتِ الْبَيْنِ، وَإِفْشَاءِ الْعَارِفَةِ، وَسَتْرِ الْعَائِبَةِ،',
 'خدایا، بر محمد و خاندانش درود فرست، و مرا به زیور شایستگان بیارای، و جامهٔ زینت پرهیزگاران را بر من بپوشان: در گستردن عدالت، و فرو خوردن خشم، و خاموش کردن آتش دشمنی، و گرد آوردن پراکندگان، و آشتی دادن میان مردم، و آشکار کردن نیکی، و پوشاندن عیب،'),
('وَلِينِ الْعَرِيكَةِ، وَخَفْضِ الْجَنَاحِ، وَحُسْنِ السِّيرَةِ، وَسُكُونِ الرِّيحِ، وَطِيبِ الْمُخَالَقَةِ، وَالسَّبْقِ إِلَى الْفَضِيلَةِ، وَإِيثَارِ التَّفَضُّلِ، وَتَرْكِ التَّعْيِيرِ، وَالْإِفْضَالِ عَلَى غَيْرِ الْمُسْتَحِقِّ،',
 'و نرم‌خویی، و فروتنی، و نیک‌رفتاری، و آرامش و وقار، و خوش‌برخوردی، و پیشی گرفتن در فضیلت، و برگزیدن بخشش، و ترک سرزنش کردن، و نیکی به کسی که سزاوارش نیست،'),
('وَالْقَوْلِ بِالْحَقِّ وَإِنْ عَزَّ، وَاسْتِقْلَالِ الْخَيْرِ وَإِنْ كَثُرَ مِنْ قَوْلِي وَفِعْلِي، وَاسْتِكْثَارِ الشَّرِّ وَإِنْ قَلَّ مِنْ قَوْلِي وَفِعْلِي،',
 'و گفتن حق هرچند دشوار باشد، و اندک شمردن خوبیِ گفتار و کردارم هرچند بسیار باشد، و بسیار شمردن بدیِ گفتار و کردارم هرچند اندک باشد.'),
('وَأَكْمِلْ ذَلِكَ لِي بِدَوَامِ الطَّاعَةِ، وَلُزُومِ الْجَمَاعَةِ، وَرَفْضِ أَهْلِ الْبِدَعِ، وَمُسْتَعْمِلِ الرَّأْيِ الْمُخْتَرَعِ.',
 'و این‌ها را برایم با پایداری در طاعت، و همراهی با جماعت [حق]، و کنار گذاشتن اهل بدعت و کسانی که رأیِ ساختگی را به کار می‌بندند، کامل کن.'),
('اللّٰهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَآلِهِ، وَاجْعَلْ أَوْسَعَ رِزْقِكَ عَلَيَّ إِذَا كَبِرْتُ، وَأَقْوَى قُوَّتِكَ فِيَّ إِذَا نَصِبْتُ، وَلَا تَبْتَلِيَنِّي بِالْكَسَلِ عَنْ عِبَادَتِكَ، وَلَا الْعَمَى عَنْ سَبِيلِكَ، وَلَا بِالتَّعَرُّضِ لِخِلَافِ مَحَبَّتِكَ، وَلَا مُجَامَعَةِ مَنْ تَفَرَّقَ عَنْكَ، وَلَا مُفَارَقَةِ مَنِ اجْتَمَعَ إِلَيْكَ.',
 'خدایا، بر محمد و خاندانش درود فرست، و گشاده‌ترین روزی‌ات را هنگام پیری‌ام، و نیرومندترین نیرویت را هنگام خستگی‌ام در من قرار ده؛ و مرا به سستی در عبادتت، و کوری از راهت، و رفتن به سوی آنچه برخلاف محبت توست، و همراهی با کسی که از تو جدا شده، و جدایی از کسی که به سوی تو گرد آمده، گرفتار مکن.'),
('اللّٰهُمَّ اجْعَلْنِي أَصُولُ بِكَ عِنْدَ الضَّرُورَةِ، وَأَسْأَلُكَ عِنْدَ الْحَاجَةِ، وَأَتَضَرَّعُ إِلَيْكَ عِنْدَ الْمَسْكَنَةِ،',
 'خدایا، چنانم کن که هنگام ناچاری به [نیروی] تو حمله کنم، و هنگام نیاز از تو بخواهم، و هنگام بیچارگی به درگاهت زاری کنم؛'),
('وَلَا تَفْتِنِّي بِالِاسْتِعَانَةِ بِغَيْرِكَ إِذَا اضْطُرِرْتُ، وَلَا بِالْخُضُوعِ لِسُؤَالِ غَيْرِكَ إِذَا افْتَقَرْتُ، وَلَا بِالتَّضَرُّعِ إِلَى مَنْ دُونَكَ إِذَا رَهِبْتُ، فَأَسْتَحِقَّ بِذَلِكَ خِذْلَانَكَ وَمَنْعَكَ وَإِعْرَاضَكَ، يَا أَرْحَمَ الرَّاحِمِينَ.',
 'و مرا به یاری خواستن از غیر تو هنگام ناچاری، و به فروتنی برای درخواست از غیر تو هنگام نیاز، و به زاری کردن نزد کسی جز تو هنگام ترس گرفتار مکن، که با این کار سزاوار وانهادن و بازداشتن و روی‌گردانی تو شوم؛ ای مهربان‌ترین مهربانان.'),
('اللّٰهُمَّ اجْعَلْ مَا يُلْقِي الشَّيْطَانُ فِي رُوعِي مِنَ التَّمَنِّي وَالتَّظَنِّي وَالْحَسَدِ ذِكْراً لِعَظَمَتِكَ، وَتَفَكُّراً فِي قُدْرَتِكَ، وَتَدْبِيراً عَلَى عَدُوِّكَ،',
 'خدایا، آنچه شیطان از آرزوپروری و بدگمانی و حسد در دلم می‌افکند، به یاد بزرگی‌ات، و اندیشیدن در قدرتت، و چاره‌اندیشی در برابر دشمنت تبدیل کن؛'),
('وَمَا أَجْرَى عَلَى لِسَانِي مِنْ لَفْظَةِ فُحْشٍ، أَوْ هُجْرٍ، أَوْ شَتْمِ عِرْضٍ، أَوْ شَهَادَةِ بَاطِلٍ، أَوِ اغْتِيَابِ مُؤْمِنٍ غَائِبٍ، أَوْ سَبِّ حَاضِرٍ، وَمَا أَشْبَهَ ذَلِكَ، نُطْقاً بِالْحَمْدِ لَكَ، وَإِغْرَاقاً فِي الثَّنَاءِ عَلَيْكَ، وَذَهَاباً فِي تَمْجِيدِكَ، وَشُكْراً لِنِعْمَتِكَ، وَاعْتِرَافاً بِإِحْسَانِكَ، وَإِحْصَاءً لِمِنَنِكَ.',
 'و هر سخن زشت، یا یاوه، یا دشنام به آبروی کسی، یا گواهی باطل، یا غیبت مؤمنی که حاضر نیست، یا ناسزا به حاضر، و مانند اینها را که [شیطان] بر زبانم می‌آورد، به گفتن ستایش تو، و غرق شدن در ثنای تو، و پیش رفتن در بزرگداشت تو، و سپاس نعمتت، و اعتراف به نیکی‌ات، و برشمردن منت‌هایت تبدیل کن.'),
('اللّٰهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَآلِهِ، وَلَا أُظْلَمَنَّ وَأَنْتَ مُطِيقٌ لِلدَّفْعِ عَنِّي، وَلَا أَظْلِمَنَّ وَأَنْتَ الْقَادِرُ عَلَى الْقَبْضِ مِنِّي، وَلَا أَضِلَّنَّ وَقَدْ أَمْكَنَتْكَ هِدَايَتِي، وَلَا أَفْتَقِرَنَّ وَمِنْ عِنْدِكَ وُسْعِي، وَلَا أَطْغَيَنَّ وَمِنْ عِنْدِكَ وُجْدِي.',
 'خدایا، بر محمد و خاندانش درود فرست، و مبادا به من ستم شود در حالی که تو توان دفع آن از من را داری، و مبادا ستم کنم در حالی که تو بر بازداشتنم توانایی، و مبادا گمراه شوم در حالی که هدایتم برایت ممکن است، و مبادا نیازمند شوم در حالی که گشایشم از نزد توست، و مبادا سرکش شوم در حالی که توانگری‌ام از نزد توست.'),
('اللّٰهُمَّ إِلَى مَغْفِرَتِكَ وَفَدْتُ، وَإِلَى عَفْوِكَ قَصَدْتُ، وَإِلَى تَجَاوُزِكَ اشْتَقْتُ، وَبِفَضْلِكَ وَثِقْتُ، وَلَيْسَ عِنْدِي مَا يُوجِبُ لِي مَغْفِرَتَكَ، وَلَا فِي عَمَلِي مَا أَسْتَحِقُّ بِهِ عَفْوَكَ، وَمَا لِي بَعْدَ أَنْ حَكَمْتُ عَلَى نَفْسِي إِلَّا فَضْلُكَ، فَصَلِّ عَلَى مُحَمَّدٍ وَآلِهِ، وَتَفَضَّلْ عَلَيَّ.',
 'خدایا، به سوی آمرزشت آمده‌ام، و آهنگ گذشتت کرده‌ام، و مشتاق چشم‌پوشی‌ات شده‌ام، و به فضلت اعتماد کرده‌ام؛ و نزد من چیزی نیست که آمرزشت را برایم واجب کند، و در کارم چیزی نیست که با آن سزاوار گذشتت شوم، و پس از آنکه بر ضد خود حکم کردم، جز فضل تو چیزی ندارم؛ پس بر محمد و خاندانش درود فرست، و بر من فضل کن.'),
('اللّٰهُمَّ وَأَنْطِقْنِي بِالْهُدَى، وَأَلْهِمْنِي التَّقْوَى، وَوَفِّقْنِي لِلَّتِي هِيَ أَزْكَى، وَاسْتَعْمِلْنِي بِمَا هُوَ أَرْضَى.',
 'خدایا، و مرا به هدایت گویا کن، و پرهیزگاری را به دلم بیفکن، و به آنچه پاکیزه‌تر است توفیقم ده، و به آنچه پسندیده‌تر است بگمارم.'),
('اللّٰهُمَّ اسْلُكْ بِيَ الطَّرِيقَةَ الْمُثْلَى، وَاجْعَلْنِي عَلَى مِلَّتِكَ أَمُوتُ وَأَحْيَا.',
 'خدایا، مرا در بهترین راه ببر، و چنانم کن که بر آیین تو بمیرم و زنده باشم.'),
('اللّٰهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَآلِهِ، وَمَتِّعْنِي بِالِاقْتِصَادِ، وَاجْعَلْنِي مِنْ أَهْلِ السَّدَادِ، وَمِنْ أَدِلَّةِ الرَّشَادِ، وَمِنْ صَالِحِ الْعِبَادِ، وَارْزُقْنِي فَوْزَ الْمَعَادِ، وَسَلَامَةَ الْمِرْصَادِ.',
 'خدایا، بر محمد و خاندانش درود فرست، و مرا از میانه‌روی بهره‌مند کن، و مرا از اهل درستی، و از راهنمایان به راه راست، و از بندگان شایسته قرار ده، و رستگاری روز بازگشت و سلامت در گذرگاهِ [حساب] را روزی‌ام کن.'),
('اللّٰهُمَّ خُذْ لِنَفْسِكَ مِنْ نَفْسِي مَا يُخَلِّصُهَا، وَأَبْقِ لِنَفْسِي مِنْ نَفْسِي مَا يُصْلِحُهَا، فَإِنَّ نَفْسِي هَالِكَةٌ أَوْ تَعْصِمَهَا.',
 'خدایا، از جانم برای خودت آن را بگیر که رهایی‌اش دهد، و از جانم برای خودم آن را باقی گذار که سامانش دهد؛ زیرا جانم نابود است مگر آنکه تو نگاهش داری.'),
('اللّٰهُمَّ أَنْتَ عُدَّتِي إِنْ حَزِنْتُ، وَأَنْتَ مُنْتَجَعِي إِنْ حُرِمْتُ، وَبِكَ اسْتِغَاثَتِي إِنْ كَرِثْتُ، وَعِنْدَكَ مِمَّا فَاتَ خَلَفٌ، وَلِمَا فَسَدَ صَلَاحٌ، وَفِيمَا أَنْكَرْتَ تَغْيِيرٌ،',
 'خدایا، اگر اندوهگین شوم تو ساز و برگ منی، و اگر محروم شوم تو مقصد منی، و اگر گرفتار شوم فریادخواهی‌ام از توست؛ و نزد توست جایگزینِ آنچه از دست رفته، و اصلاحِ آنچه تباه شده، و دگرگون کردنِ آنچه ناپسند داشتی.'),
('فَامْنُنْ عَلَيَّ قَبْلَ الْبَلَاءِ بِالْعَافِيَةِ، وَقَبْلَ الطَّلَبِ بِالْجِدَةِ، وَقَبْلَ الضَّلَالِ بِالرَّشَادِ، وَاكْفِنِي مَؤُونَةَ مَعَرَّةِ الْعِبَادِ، وَهَبْ لِي أَمْنَ يَوْمِ الْمَعَادِ، وَامْنَحْنِي حُسْنَ الْإِرْشَادِ.',
 'پس پیش از بلا با عافیت، و پیش از درخواست با توانگری، و پیش از گمراهی با راه راست بر من منت گذار؛ و مرا از رنج آزار بندگان کفایت کن، و امنیت روز بازگشت را به من ببخش، و راهنمایی نیکو را به من عطا کن.'),
('اللّٰهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَآلِهِ، وَادْرَأْ عَنِّي بِلُطْفِكَ، وَاغْذُنِي بِنِعْمَتِكَ، وَأَصْلِحْنِي بِكَرَمِكَ، وَدَاوِنِي بِصُنْعِكَ، وَأَظِلَّنِي فِي ذَرَاكَ، وَجَلِّلْنِي رِضَاكَ،',
 'خدایا، بر محمد و خاندانش درود فرست، و با لطفت [بدی‌ها را] از من دور کن، و با نعمتت مرا بپرور، و با کرمت اصلاحم کن، و با کارسازی‌ات درمانم کن، و در پناهت بر من سایه افکن، و خشنودی‌ات را سراپای من بپوشان.'),
('وَوَفِّقْنِي إِذَا اشْتَكَلَتْ عَلَيَّ الْأُمُورُ لِأَهْدَاهَا، وَإِذَا تَشَابَهَتِ الْأَعْمَالُ لِأَزْكَاهَا، وَإِذَا تَنَاقَضَتِ الْمِلَلُ لِأَرْضَاهَا.',
 'و هرگاه کارها بر من مشتبه شد، به درست‌ترینشان، و هرگاه کارها به هم ماننده شد، به پاکیزه‌ترینشان، و هرگاه آیین‌ها با هم ناسازگار شد، به پسندیده‌ترینشان توفیقم ده.'),
('اللّٰهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَآلِهِ، وَتَوِّجْنِي بِالْكِفَايَةِ، وَسُمْنِي حُسْنَ الْوِلَايَةِ، وَهَبْ لِي صِدْقَ الْهِدَايَةِ، وَلَا تَفْتِنِّي بِالسَّعَةِ، وَامْنَحْنِي حُسْنَ الدَّعَةِ، وَلَا تَجْعَلْ عَيْشِي كَدّاً كَدّاً، وَلَا تَرُدَّ دُعَائِي عَلَيَّ رَدّاً، فَإِنِّي لَا أَجْعَلُ لَكَ ضِدّاً، وَلَا أَدْعُو مَعَكَ نِدّاً.',
 'خدایا، بر محمد و خاندانش درود فرست، و تاج بی‌نیازی بر سرم بگذار، و سرپرستی نیکو را نشان من کن، و هدایت راستین را به من ببخش، و مرا با گشایش [مال] گرفتار مکن، و آسایش نیکو به من عطا کن، و زندگی‌ام را رنج پشت رنج قرار مده، و دعایم را به من بازمگردان؛ زیرا من برای تو ضدی قرار نمی‌دهم، و همتایی را همراه تو نمی‌خوانم.'),
('اللّٰهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَآلِهِ، وَامْنَعْنِي مِنَ السَّرَفِ، وَحَصِّنْ رِزْقِي مِنَ التَّلَفِ، وَوَفِّرْ مَلَكَتِي بِالْبَرَكَةِ فِيهِ، وَأَصِبْ بِي سَبِيلَ الْهِدَايَةِ لِلْبِرِّ فِيمَا أُنْفِقُ مِنْهُ.',
 'خدایا، بر محمد و خاندانش درود فرست، و مرا از اسراف بازدار، و روزی‌ام را از تباه شدن نگاه دار، و دارایی‌ام را با برکت دادن در آن فزونی بخش، و در آنچه از آن خرج می‌کنم، مرا به راه درستِ نیکوکاری برسان.'),
('اللّٰهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَآلِهِ، وَاكْفِنِي مَؤُونَةَ الِاكْتِسَابِ، وَارْزُقْنِي مِنْ غَيْرِ احْتِسَابٍ، فَلَا أَشْتَغِلَ عَنْ عِبَادَتِكَ بِالطَّلَبِ، وَلَا أَحْتَمِلَ إِصْرَ تَبِعَاتِ الْمَكْسَبِ.',
 'خدایا، بر محمد و خاندانش درود فرست، و مرا از رنج کسب کفایت کن، و از جایی که گمان ندارم روزی‌ام ده، تا با جستجوی روزی از عبادتت بازنمانم، و بار سنگین پیامدهای کسب را بر دوش نکشم.'),
('اللّٰهُمَّ فَأَطْلِبْنِي بِقُدْرَتِكَ مَا أَطْلُبُ، وَأَجِرْنِي بِعِزَّتِكَ مِمَّا أَرْهَبُ.',
 'خدایا، پس با قدرتت آنچه را می‌جویم برایم فراهم کن، و با عزتت از آنچه می‌ترسم پناهم ده.'),
('اللّٰهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَآلِهِ، وَصُنْ وَجْهِي بِالْيَسَارِ، وَلَا تَبْتَذِلْ جَاهِي بِالْإِقْتَارِ، فَأَسْتَرْزِقَ أَهْلَ رِزْقِكَ، وَأَسْتَعْطِيَ شِرَارَ خَلْقِكَ، فَأَفْتَتِنَ بِحَمْدِ مَنْ أَعْطَانِي، وَأُبْتَلَى بِذَمِّ مَنْ مَنَعَنِي، وَأَنْتَ مِنْ دُونِهِمْ وَلِيُّ الْإِعْطَاءِ وَالْمَنْعِ.',
 'خدایا، بر محمد و خاندانش درود فرست، و آبرویم را با توانگری نگاه دار، و جایگاهم را با تنگدستی بی‌ارزش مکن، که از روزی‌خورانِ تو روزی بخواهم، و از بدترین آفریدگانت بخشش طلبم، و آنگاه به ستایش کسی که به من داده گرفتار شوم، و به نکوهش کسی که دریغ کرده مبتلا گردم؛ در حالی که تو، نه آنان، صاحب اختیار دادن و ندادنی.'),
('اللّٰهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَآلِهِ، وَارْزُقْنِي صِحَّةً فِي عِبَادَةٍ، وَفَرَاغاً فِي زَهَادَةٍ، وَعِلْماً فِي اسْتِعْمَالٍ، وَوَرَعاً فِي إِجْمَالٍ.',
 'خدایا، بر محمد و خاندانش درود فرست، و تندرستی همراه با عبادت، و فراغت همراه با بی‌رغبتی به دنیا، و دانشی همراه با به کار بستن، و پارسایی همراه با میانه‌روی را روزی‌ام کن.'),
('اللّٰهُمَّ اخْتِمْ بِعَفْوِكَ أَجَلِي، وَحَقِّقْ فِي رَجَاءِ رَحْمَتِكَ أَمَلِي، وَسَهِّلْ إِلَى بُلُوغِ رِضَاكَ سُبُلِي، وَحَسِّنْ فِي جَمِيعِ أَحْوَالِي عَمَلِي.',
 'خدایا، پایان عمرم را با گذشتت به سر رسان، و آرزویم را در امید به رحمتت تحقق بخش، و راه‌هایم را برای رسیدن به خشنودی‌ات هموار کن، و کارم را در همهٔ حالاتم نیکو گردان.'),
('اللّٰهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَآلِهِ، وَنَبِّهْنِي لِذِكْرِكَ فِي أَوْقَاتِ الْغَفْلَةِ، وَاسْتَعْمِلْنِي بِطَاعَتِكَ فِي أَيَّامِ الْمُهْلَةِ، وَانْهَجْ لِي إِلَى مَحَبَّتِكَ سَبِيلاً سَهْلَةً، أَكْمِلْ لِي بِهَا خَيْرَ الدُّنْيَا وَالْآخِرَةِ.',
 'خدایا، بر محمد و خاندانش درود فرست، و در هنگام‌های غفلت مرا به یاد خود بیدار کن، و در روزهای مهلت مرا به طاعتت بگمار، و راهی هموار به سوی محبتت برایم بگشا، که با آن خیر دنیا و آخرت را برایم کامل کنی.'),
('اللّٰهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَآلِهِ، كَأَفْضَلِ مَا صَلَّيْتَ عَلَى أَحَدٍ مِنْ خَلْقِكَ قَبْلَهُ، وَأَنْتَ مُصَلٍّ عَلَى أَحَدٍ بَعْدَهُ، وَآتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الْآخِرَةِ حَسَنَةً، وَقِنِي بِرَحْمَتِكَ عَذَابَ النَّارِ.',
 'خدایا، بر محمد و خاندانش درود فرست، مانند برترین درودی که پیش از او بر یکی از آفریدگانت فرستادی، و پس از او بر کسی خواهی فرستاد؛ و در دنیا به ما نیکی و در آخرت نیکی عطا کن، و به رحمتت مرا از عذاب آتش نگاه دار.'),
])
